'use strict';
// Frontier contracts are offered by Roderik only; Brand keeps his original rosters.
(() => {
  const XP_BASIS_POINTS=1800;
  function freeze(value){if(value&&typeof value==='object'){Object.values(value).forEach(freeze);Object.freeze(value);}return value;}
  const LOCATIONS=freeze([
    {id:'ash-wood',name:'Popielny Bór',levels:[31,34],tile:0,description:'Spalony bór na dawnym szlaku z Ubocza. Pod korą drzew tli się obcy żar, a zwierzęta noszą ślady skażenia z południowych szczelin.'},
    {id:'dead-marsh',name:'Martwe Rozlewiska',levels:[35,38],tile:1,description:'Zatopiony trakt karawan. Zielone ogniki prowadzą między groblami, gdzie osiadł popiół niesiony od wulkanicznych pustkowi.'},
    {id:'black-ember-mine',name:'Kopalnie Czarnego Żaru',levels:[39,42],tile:2,description:'Opuszczone sztolnie na skraju wulkanicznego pasma. Górnicy przebili warstwę czarnej rudy, która nadal zasila wygasłe piece.'},
    {id:'burnt-oath-ruins',name:'Ruiny Spalonej Przysięgi',levels:[43,46],tile:3,description:'Ruiny strażnicy przy dawnym trakcie ku Wrotom. Pęknięte kamienie przysięgi budzą zbroje i przyciągają istoty żywiące się magią pieczęci.'},
    {id:'hell-approach',name:'Przedpola Piekielnych Wrót',levels:[47,50],tile:4,description:'Zewnętrzne bazaltowe pustkowia, daleko przed właściwą bramą. Zwiadowcy spotykają tu pomniejsze istoty żaru; same Wrota pozostają krainą od poziomu 110.'}
  ].map(place=>({...place,image:'frontier-locations.webp',columns:3,rows:2})));
  const rows=[
    ['ember-wolf','Żarłacz Popiołu',31,960,'predator','Żar na trakcie','Czarny wilk tropi wozy pod osłoną popielnej mgły. Płonące ślady kończą się zawsze przy tej samej wypalonej sośnie.',{special:{type:'power',every:4,multiplier:130,ability:'ember-pounce'},traits:'Co czwarty własny atak: skok zadaje 130% bazowych obrażeń.'}],
    ['ashen-stag','Jeleń Spopielonych Rogów',32,1020,'predator','Rogi wśród zgliszcz','Skażony jeleń rozbija palisady drwali. Jego poroże przypomina gałęzie, które nigdy nie przestały się żarzyć.',{special:{type:'power',every:4,multiplier:140,ability:'ashen-charge'},traits:'Co czwarty własny atak: szarża zadaje 140% bazowych obrażeń.'}],
    ['cinder-thornwalker','Ciernisty Pogorzelec',33,1100,'brute','Ciernie na starej drodze','Spalony drzewiec wrasta korzeniami w drogę i chwyta podróżnych kolczastymi konarami.',{special:{type:'flat',every:4,bonus:25,ability:'cinder-thorns'},traits:'Co czwarty własny atak: kolczasty konar dodaje 25 bazowych obrażeń.'}],
    ['last-ember-guardian','Strażnik Ostatniego Żaru',34,1200,'brute','Serce popielnego boru','Dawny obrońca lasu strzeże tlącego się korzenia. Skażenie zamieniło jego korę w twardy węgiel.',{physicalArmor:6,waterWeakness:20,traits:'Pochłania 6 obrażeń fizycznych z trafienia. Otrzymuje 20% więcej obrażeń od wody.'}],
    ['drowned-ferryman','Utopiony Przewoźnik',35,1260,'caster','Ostatnia przeprawa','Widmo pobiera myto od pustych łodzi. Jego latarnia wysysa ciepło z każdego, kto stąpi na groblę.',{attackElement:'magic',traits:'Magiczny atak omija obronę fizyczną; ogólny pancerz nadal działa.'}],
    ['mire-hydra','Hydra Martwej Grobli',36,1340,'predator','Trzy głowy pod wodą','Trzygłowa bestia poluje pod zawaloną groblą. Jad z jej paszczy zatruwa resztki czystej wody.',{special:{type:'dot',every:4,damage:18,turns:3,label:'Jad hydry',ability:'mire-venom'},traits:'Co czwarty własny atak: jad zadaje 18 obrażeń na początku 3 kolejnych tur celu.'}],
    ['marsh-mourner','Żałobnica Rozlewisk',37,1400,'caster','Pieśń nad czarną wodą','Z mgły dobiega pieśń zaginionej karawany. Widmo więzi głosy podróżnych w zatopionej kapliczce.',{special:{type:'magic-wave',every:4,damage:35,ability:'mourning-echo'},physicalResistance:10,magicVulnerability:15,traits:'Co czwarty własny atak: dodatkowa fala 35 obrażeń magicznych. Odporność fizyczna 10%; podatność na magię 15%.'}],
    ['peat-colossus','Torfowy Kolos',38,1510,'brute','Grobla, która chodzi','Olbrzym z torfu i belek mostowych odcina przejście. W jego wnętrzu migoczą zielone ogniki.',{special:{type:'power',every:5,multiplier:135,ability:'causeway-slam'},traits:'Co piąty własny atak: uderzenie zadaje 135% bazowych obrażeń.'}],
    ['slag-scorpion','Żużlowy Skorpion',39,1580,'predator','Żądło w czarnej rudzie','Wózki wracają ze sztolni z pogiętymi kołami. Skorpion osłania odwłok płytami ostrego żużla.',{armor:6,special:{type:'dot',every:4,damage:20,turns:2,label:'Jad skorpiona',ability:'slag-sting'},traits:'Pancerz pochłania 6 obrażeń. Co czwarty własny atak: jad zadaje 20 obrażeń przez 2 tury celu.'}],
    ['chained-overseer','Zakuty Nadzorca',40,1650,'brute','Łańcuch ostatniej zmiany','Nadzorca bez twarzy nadal zagania niewidzialnych górników do pracy, uderzając łańcuchem o tory.',{special:{type:'piercing',every:4,piercing:25,ability:'overseer-chain'},traits:'Co czwarty własny atak ignoruje 25% redukcji pancerza i odporności fizycznej.'}],
    ['black-iron-golem','Golem Czarnej Rudy',41,1760,'brute','Ruda, która nie stygnie','Opuszczony strażnik pieca naprawia się płytami czarnej stali. Jego rdzeń reaguje na zaklęcia.',{physicalArmor:10,magicVulnerability:15,traits:'Pochłania 10 obrażeń fizycznych. Otrzymuje 15% więcej obrażeń magicznych.'}],
    ['living-furnace','Żywy Piec',42,1840,'caster','Oddech pod kuźnią','Żar w opuszczonej kuźni zyskał kamienne ciało. Rozgrzane powietrze zapowiada każdy jego atak.',{attackElement:'fire',waterWeakness:30,traits:'Atakuje ogniem, omijając obronę fizyczną. Otrzymuje 30% więcej obrażeń od wody.'}],
    ['broken-vow-knight','Rycerz Złamanych Ślubów',43,1910,'brute','Przysięga bez świadka','Zbroja dawnego rycerza obchodzi spalony dziedziniec. Na tarczy pozostał przecięty znak przysięgi.',{special:{type:'piercing',every:4,piercing:30,ability:'oathbreaker-cut'},traits:'Co czwarty własny atak ignoruje 30% redukcji pancerza i odporności fizycznej.'}],
    ['seal-eater','Pożeracz Pieczęci',44,1990,'caster','Głód starego kamienia','Kamienna bestia wygryza runy z murów. Zjedzona magia wraca jako gwałtowny fioletowy impuls.',{special:{type:'magic-wave',every:4,damage:35,ability:'stolen-seal'},traits:'Co czwarty własny atak dodaje falę 35 bazowych obrażeń magicznych.'}],
    ['choir-wraith','Widmo Spalonego Chóru',45,2070,'caster','Głosy pod sklepieniem','Rój ceremonialnych masek otacza jedną postać. Każda maska powtarza inną, niedokończoną przysięgę.',{attackElement:'magic',physicalResistance:10,magicVulnerability:20,traits:'Magiczne ataki; odporność fizyczna 10% i podatność na magię 20%.'}],
    ['fallen-oath-custodian','Upadły Kustosz Przysięgi',46,2180,'brute','Ostatni kustosz','Kustosz pilnuje pustego ołtarza i atakuje każdego, kto próbuje zbliżyć się do zgasłej pieczęci.',{physicalArmor:8,special:{type:'power',every:5,multiplier:140,ability:'custodian-verdict'},traits:'Pochłania 8 obrażeń fizycznych. Co piąty własny atak zadaje 140% bazowych obrażeń.'}],
    ['foregate-hellhound','Ogar Piekielnego Pogranicza',47,2240,'predator','Trop gorący jak żelazo','Ogar przedostał się przez szczeliny daleko przed Wrotami. Jego ślady wypalają kręgi w bazalcie.',{attackElement:'fire',enrage:{threshold:30,bonus:15},traits:'Atakuje ogniem. Poniżej 30% HP zadaje 15% więcej bazowych obrażeń.'}],
    ['basalt-gargoyle','Bazaltowy Gargulec',48,2330,'predator','Cień nad posterunkiem','Skrzydlata bestia udaje fragment zrujnowanej wieży. Pod kamiennymi płytami widać pasma żaru.',{physicalArmor:12,magicVulnerability:15,traits:'Pochłania 12 obrażeń fizycznych. Otrzymuje 15% więcej obrażeń magicznych.'}],
    ['ash-summoner','Przywoływacz Popiołów',49,2410,'caster','Krąg popielnej burzy','Zakapturzony przywoływacz zbiera żar z pustkowi. W popiele układa niewielkie przejścia dla ogarów.',{attackElement:'fire',waterWeakness:20,special:{type:'magic-wave',every:4,damage:40,ability:'ash-storm'},traits:'Atakuje ogniem; co czwarty własny atak dodaje falę 40 obrażeń magicznych. Podatność na wodę 20%.'}],
    ['foregate-sentinel','Strażnik Przedbramia',50,2500,'brute','Halabarda przedbramia','Pomniejszy strażnik zewnętrznego traktu nosi pancerz z bazaltu. Broni posterunku, nie właściwych Wrót.',{physicalArmor:10,magicVulnerability:10,special:{type:'power',every:5,multiplier:145,ability:'foregate-cleave'},traits:'Pochłania 10 obrażeń fizycznych; podatność na magię 10%. Co piąty własny atak zadaje 145% bazowych obrażeń.'}]
  ];
  function threshold(level){const need=Number.isSafeInteger(level)&&level>0?window.Progression.required(level):null;if(!Number.isSafeInteger(need)||need<=0)throw Error('Brak progu EXP dla tego poziomu.');return need;}
  const MONSTERS=freeze(rows.map(([id,name,level,maxHp,kind,contractTitle,description,rules],index)=>{
    const scene=LOCATIONS[Math.floor(index/4)],power=Math.round(level*2.2),secondary=Math.round(level*1.3);
    const attackMin=150+7*(level-30),gold=300+25*index+5*Math.floor(index/4);
    const tile=index%4,crop=scene.id==='burnt-oath-ruins'?{x:tile%2*.5,y:tile<2?0:548/1254,width:.5,height:tile<2?548/1254:706/1254}:null;
    return {id,name,level,maxHp,stats:kind==='caster'?[level,secondary,power,Math.round(maxHp/10)]:kind==='predator'?[power,power,level,Math.round(maxHp/10)]:[power,secondary,level,Math.round(maxHp/10)],attack:[attackMin,attackMin+20+index],sceneId:scene.id,description,contractTitle,...rules,reward:{xp:Math.floor(threshold(level)*XP_BASIS_POINTS/10000),gold},rewardVersion:1,image:`frontier-monsters-${scene.id}.webp`,columns:2,rows:2,tile,crop};
  }));
  function get(id){const monster=MONSTERS.find(enemy=>enemy.id===id);if(!monster)throw Error('Nieznany potwór pogranicza.');return monster;}
  function rewardFor(id,playerLevel=get(id).level){const enemy=get(id);return {gold:enemy.reward.gold,xp:Math.floor(Math.min(threshold(playerLevel),threshold(enemy.level))*XP_BASIS_POINTS/10000)};}
  window.FrontierBestiary=freeze({VERSION:1,STATUS:'available-at-roderik',MISSION_POOL_ENABLED:true,XP_BASIS_POINTS,LOCATIONS,MONSTERS,get,rewardFor,atLevel:level=>MONSTERS.find(enemy=>enemy.level===level)??null});
})();
